declare
  g constant uuid := 'ceed8c90-4245-4396-9095-d1d858d397ac';
  es_id constant uuid := '2ac6ac2b-ce9e-458c-b43d-93ea541ea20c';
  j constant jsonb := $pol$[{"id":"2ac6ac2b-ce9e-458c-b43d-93ea541ea20c","recipe_group_id":"ceed8c90-4245-4396-9095-d1d858d397ac","language":"es","slug":"pollo-al-limon-y-miel-con-esparragos-asados","public_path":"/pollo-al-limon-y-miel-con-esparragos-asados","source_url":"https://manualdecocina.com/pollo-al-limon-y-miel-con-esparragos-asados/","title":"Pollo al limón y miel con espárragos asados","excerpt":"Pechugas con salsa de limón, miel y ajo, y espárragos asados por separado. Una propuesta para 4 con control de temperatura a 74 °C.","summary":"Pechugas doradas en sartén y terminadas en una salsa de limón, miel y ajo, con espárragos verdes asados por separado. La miel entra después de dorar el pollo, a fuego suave, para reducir el riesgo de que se queme. Se conserva la identidad y la URL histórica de esta receta.\n\nLa propuesta rinde 4 porciones, cada una con una pieza de pollo y un cuarto de los espárragos y de la salsa. Se estiman 15 minutos de preparación, 25 de cocción con tareas en paralelo y 5 de reposo: 45 en total. Cantidades, tiempos y rendimiento quedan pendientes de prueba de cocina. Comprueba 74 °C en cada pieza; el color y el tiempo no certifican la cocción.","category":"Platos principales","category_slug":"platos-principales","difficulty":"Fácil","course":"Plato principal","cuisine":"Cocina casera","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["pollo al limón","pollo con miel","espárragos asados","pechugas en salsa"],"ingredients":[{"name":"pechuga de pollo cruda sin piel ni hueso","amount":"800","unit":"g","group":"Pollo"},{"name":"espárragos verdes, peso después de recortar","amount":"600","unit":"g","group":"Guarnición"},{"name":"zumo de limón recién exprimido","amount":"40","unit":"g","group":"Salsa"},{"name":"miel","amount":"40","unit":"g","group":"Salsa"},{"name":"aceite de oliva","amount":"30","unit":"g","group":"Cocción y sazonado"},{"name":"ajo","amount":"10","unit":"g","group":"Salsa"},{"name":"sal fina","amount":"4","unit":"g","group":"Cocción y sazonado"},{"name":"pimienta negra molida","amount":"0.5","unit":"g","group":"Cocción y sazonado"},{"name":"agua potable","amount":"60","unit":"ml","group":"Salsa"}],"steps":[{"title":"Prepara el pollo y los espárragos","content":"Precalienta el horno a 210 °C con calor arriba y abajo, sin ventilador. Lava los espárragos, recorta las bases duras y pesa 600 g ya limpios; seca bien. En una tabla aparte prepara 4 piezas de pechuga que sumen 800 g, de unos 200 g cada una, con grosor uniforme de 1,5–2 cm; abre las más gruesas si hace falta. No laves el pollo crudo. Separa utensilios crudos y cocidos. Reserva 3 g de sal y 0,25 g de pimienta para el pollo, y 1 g de sal y 0,25 g de pimienta para los espárragos.","image_alt":"Espárragos limpios en una tabla y cuatro pechugas crudas en otra tabla separada","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-01.webp"},{"title":"Mezcla la salsa en un recipiente limpio","content":"Mezcla los 40 g de zumo de limón, 40 g de miel, 10 g de ajo picado y 60 ml de agua potable. Remueve hasta disolver la miel. Mantén esta salsa en un recipiente limpio y evita que toque el pollo crudo; no es una marinada ni se reutilizan jugos del plato crudo.","image_alt":"Salsa de limón, miel y ajo mezclándose en un cuenco, sin contacto con pollo crudo","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-02.webp"},{"title":"Asa los espárragos por separado","content":"Reparte los espárragos en una bandeja, en una sola capa, con 10 g del aceite, 1 g de sal y 0,25 g de pimienta. Hornea a 210 °C unos 12–18 minutos, girándolos al cumplir 8 minutos, hasta que estén tiernos con algo de firmeza y las puntas ligeramente doradas. El grosor modifica el tiempo. Haz esta tarea mientras cocinas el pollo; si terminan antes, mantenlos brevemente cubiertos mientras acabas la salsa. No pongas pollo crudo en esta bandeja.","image_alt":"Espárragos verdes asados en una sola capa en una bandeja sin pollo","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-03.webp"},{"title":"Dora las cuatro piezas de pollo","content":"Calienta los otros 20 g de aceite en una sartén amplia a fuego medio. Sazona el pollo con los 3 g de sal y 0,25 g de pimienta reservados. Coloca las 4 piezas sin amontonarlas y dora unos 4 minutos por cada lado, aproximadamente 8 minutos en total. Ajusta el fuego para dorar sin quemar. En esta fase no añadas miel ni salsa y no des por cocinado el centro.","image_alt":"Cuatro pechugas dorándose en una sartén amplia sin salsa ni espárragos","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-04.webp"},{"title":"Termina con la salsa y comprueba la temperatura","content":"Baja el fuego, añade toda la salsa limpia del paso 2 y cocina a hervor suave unos 6–8 minutos, girando el pollo para cubrirlo. Si espesa demasiado pronto, baja más el fuego y tapa brevemente; no dejes que el azúcar oscurezca o se queme. Mide cada pieza con una sonda limpia en el centro más grueso, sin tocar la sartén: debe alcanzar al menos 74 °C. Si no llega, prolonga la cocción a fuego suave y vuelve a medir. La salsa debe quedar fluida y ligeramente brillante, no como un caramelo espeso.","image_alt":"Pechugas cocinadas cubiertas de salsa ligera de limón y miel en la sartén","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-05.webp"},{"title":"Reposa, sirve y conserva con seguridad","content":"Retira el pollo a una fuente limpia y reposa 5 minutos. Divide en 4 porciones y reparte los espárragos y toda la salsa; usa utensilios limpios. Para guardar, distribuye las sobras en recipientes bajos y refrigera a 4 °C o menos dentro de 2 horas, o 1 hora si el ambiente supera 32 °C. Se propone consumirlas en 3 días y recalentar la porción una sola vez hasta 74 °C en el centro. No dejes pollo cocinado en el plato que contuvo el crudo.","image_alt":"Una pechuga con salsa de limón y miel junto a espárragos asados en un plato","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-06.webp"}],"notes":"La miel no es adecuada para menores de 12 meses. Revisa alérgenos en productos envasados y usa pollo sin salmuera añadida para aproximarte al cálculo. No se incluye mostaza, salsa de soja, mantequilla, caldo ni guarniciones extra. Puedes usar espárragos blancos al mismo peso, ajustando pelado y cocción; el resultado y la nutrición cambian. No sustituyas la miel por edulcorantes como cambio equivalente: su textura, sabor y reducción son distintos. El zumo es la parte comestible contada, no se añaden rodajas de limón ni hierbas al plato. Los espárragos se pesan después de quitar las bases duras. La nutrición cuenta toda la salsa y el aceite repartidos entre 4; si queda parte en la sartén, la ingesta real puede ser menor. No se ha validado aquí la congelación ni el uso de sobras previas.","nutrition":{"fat_g":13,"calories":372.9,"saturated_fat_g":2.2,"sodium_mg":482,"protein_g":48.5,"sugar_g":11.3,"carbs_g":15.7,"fiber_g":3.3,"estimated":true,"serving_size":"1 de 4 porciones propuestas","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Ocho fichas USDA verificadas por FDC ID en el archivo oficial. Pesos comestibles crudos sumados y divididos entre 4; se cuentan toda la salsa, el aceite y el sazonado. Los 60 ml de agua potable no aportan energía y se excluyen de los ocho inputs. No se calculan pérdidas de nutrientes ni reparto exacto después de cocinar.","note":"Estimación, no análisis del plato cocinado. La salmuera del pollo, el tipo de miel, las pérdidas y el reparto real alteran las cifras; cantidades, tiempos y rendimiento pendientes de prueba de cocina.","inputs":[{"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120,"saturated_fat_g":0.563,"sodium_mg":45,"protein_g":22.5,"sugar_g":0,"carbs_g":0,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients","ingredient":"pechuga de pollo cruda","edible_grams":800},{"fdc_id":168389,"fdc_description":"Asparagus, raw","per_100g":{"saturated_fat_g":0.04,"protein_g":2.2,"sugar_g":1.88,"sodium_mg":2,"carbs_g":3.88,"calories":20,"fiber_g":2.1,"fat_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168389/nutrients","ingredient":"espárragos crudos recortados","edible_grams":600},{"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients","ingredient":"zumo de limón","edible_grams":40},{"fdc_id":169640,"fdc_description":"Honey","per_100g":{"saturated_fat_g":0,"protein_g":0.3,"fiber_g":0.2,"sodium_mg":4,"fat_g":0,"carbs_g":82.4,"calories":304,"sugar_g":82.1},"source_url":"https://fdc.nal.usda.gov/food-details/169640/nutrients","ingredient":"miel","edible_grams":40},{"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"fat_g":100,"carbs_g":0,"calories":884,"sodium_mg":2,"protein_g":0,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients","ingredient":"aceite de oliva","edible_grams":30},{"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.1,"calories":149,"sugar_g":1,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients","ingredient":"ajo","edible_grams":10},{"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38800,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients","ingredient":"sal","edible_grams":4},{"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":64,"calories":251,"protein_g":10.4,"fiber_g":25.3,"sodium_mg":20,"saturated_fat_g":1.39},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients","ingredient":"pimienta negra","edible_grams":0.5}]},"image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","gallery":[{"url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","alt":"Una pechuga con salsa de limón y miel junto a espárragos asados en un plato"}],"seo":{"title":"Pollo al limón y miel con espárragos | Manual de Cocina","description":"Pollo con salsa de limón, miel y ajo para 4, junto a espárragos asados. Dora primero, añade la salsa después y comprueba 74 °C en cada pieza.","image_alt":"Una pechuga con salsa de limón y miel junto a espárragos asados en un plato","image_variants":["/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-1x1.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-4x3.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-16x9.webp"],"faq":[{"q":"¿Cómo evito que la miel se queme?","a":"Dora el pollo sin miel y añade la salsa al bajar el fuego. Mantén un hervor suave y tapa brevemente si reduce antes de que el pollo alcance 74 °C. No busques una salsa oscura y espesa."},{"q":"¿Puedo asar los espárragos junto al pollo crudo?","a":"Esta ficha los cocina por separado. Los espárragos tienen otro tiempo y no deben recibir jugos crudos de pollo si van a retirarse antes. Usa una bandeja limpia para la guarnición."},{"q":"¿Cómo guardo y recaliento las sobras?","a":"Refrigera en recipientes bajos dentro de 2 horas, o 1 hora por encima de 32 °C, a 4 °C o menos. Se propone consumir en 3 días y recalentar una vez hasta 74 °C en el centro."}]},"published":false,"editorial_status":"draft","content_html":"<p>Pechugas doradas en sartén y terminadas en una salsa de limón, miel y ajo, con espárragos verdes asados por separado. La miel entra después de dorar el pollo, a fuego suave, para reducir el riesgo de que se queme. Se conserva la identidad y la URL histórica de esta receta.</p><p>La propuesta rinde 4 porciones, cada una con una pieza de pollo y un cuarto de los espárragos y de la salsa. Se estiman 15 minutos de preparación, 25 de cocción con tareas en paralelo y 5 de reposo: 45 en total. Cantidades, tiempos y rendimiento quedan pendientes de prueba de cocina. Comprueba 74 °C en cada pieza; el color y el tiempo no certifican la cocción.</p>"},{"id":"b631ebf6-8c4c-533e-9d72-3b505e5f6cb5","recipe_group_id":"ceed8c90-4245-4396-9095-d1d858d397ac","language":"de","slug":"kostliches-zitronen-honig-hahnchen-rezept-mit-gerostetem-spargel-2","public_path":"/de/kostliches-zitronen-honig-hahnchen-rezept-mit-gerostetem-spargel-2","source_url":null,"title":"Zitronen-Honig-Hähnchen mit geröstetem Spargel","excerpt":"Hähnchenbrust mit Zitronen-Honig-Knoblauch-Sauce und separat geröstetem Spargel. Rezeptvorschlag für 4 mit Temperaturkontrolle bei 74°C.","summary":"Hähnchenbrüste werden in der Pfanne angebraten und anschließend in Zitronen-Honig-Knoblauch-Sauce fertig gegart. Grüner Spargel wird separat geröstet. Honig kommt erst nach dem Anbraten bei milder Hitze hinzu, damit er weniger leicht verbrennt. Die historische Identität und URL bleiben erhalten.\n\nVorgeschlagen sind 4 Portionen mit je einem Stück Hähnchen und einem Viertel von Spargel und Sauce. Geschätzt werden 15 Minuten Vorbereitung,25 Minuten teilweise paralleles Garen und 5 Minuten Ruhezeit: insgesamt 45 Minuten. Mengen, Zeiten und Ausbeute sind noch nicht in der Küche erprobt. Jedes Stück muss 74°C erreichen; Farbe und Zeit beweisen keine sichere Garung.","category":"Hauptgerichte","category_slug":"platos-principales","difficulty":"Einfach","course":"Hauptgericht","cuisine":"Hausmannskost","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["Zitronenhähnchen","Honighähnchen","gerösteter Spargel","Hähnchenbrust in Sauce"],"ingredients":[{"name":"rohe Hähnchenbrust ohne Haut und Knochen","amount":"800","unit":"g","group":"Hähnchen"},{"name":"grüner Spargel, nach dem Putzen gewogen","amount":"600","unit":"g","group":"Beilage"},{"name":"frisch gepresster Zitronensaft","amount":"40","unit":"g","group":"Sauce"},{"name":"Honig","amount":"40","unit":"g","group":"Sauce"},{"name":"Olivenöl","amount":"30","unit":"g","group":"Garen und Würzen"},{"name":"Knoblauch","amount":"10","unit":"g","group":"Sauce"},{"name":"feines Salz","amount":"4","unit":"g","group":"Garen und Würzen"},{"name":"gemahlener schwarzer Pfeffer","amount":"0.5","unit":"g","group":"Garen und Würzen"},{"name":"Trinkwasser","amount":"60","unit":"ml","group":"Sauce"}],"steps":[{"title":"Hähnchen und Spargel vorbereiten","content":"Backofen auf 210°C Ober-/Unterhitze ohne Umluft vorheizen. Spargel waschen, harte Enden abschneiden und 600 g geputzten Spargel abwiegen; gut trocknen. Auf einem separaten Brett 4 Hähnchenbruststücke mit zusammen 800 g, je etwa 200 g und gleichmäßiger Dicke von 1,5–2 cm vorbereiten; dickere Stücke bei Bedarf aufklappen. Rohes Hähnchen nicht waschen. Geräte für rohe und gegarte Lebensmittel trennen.3 g Salz und 0,25 g Pfeffer fürs Hähnchen sowie 1 g Salz und 0,25 g Pfeffer für den Spargel bereitstellen.","image_alt":"Geputzter Spargel auf einem Brett und vier rohe Hähnchenbrüste auf einem separaten Brett","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-01.webp"},{"title":"Sauce in einem sauberen Gefäß mischen","content":"40 g Zitronensaft,40 g Honig,10 g gehackten Knoblauch und 60 ml Trinkwasser verrühren, bis der Honig gelöst ist. Sauce in einem sauberen Gefäß halten und Kontakt mit rohem Hähnchen vermeiden. Sie ist keine Marinade; Saft vom Teller mit rohem Fleisch wird nicht verwendet.","image_alt":"Zitronen-Honig-Knoblauch-Sauce wird ohne Kontakt mit rohem Hähnchen in einer Schüssel verrührt","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-02.webp"},{"title":"Spargel separat rösten","content":"Spargel in einer Lage auf einem Blech mit 10 g vom Öl,1 g Salz und 0,25 g Pfeffer verteilen. Bei 210°C etwa 12–18 Minuten rösten und nach 8 Minuten wenden, bis er bissfest mit leicht gebräunten Spitzen ist. Die Dicke beeinflusst die Zeit. Parallel zum Hähnchen garen; ist der Spargel früher fertig, kurz abgedeckt halten, während die Sauce fertig wird. Kein rohes Hähnchen auf dieses Blech legen.","image_alt":"Grüner gerösteter Spargel in einer Lage auf einem Blech ohne Hähnchen","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-03.webp"},{"title":"Vier Hähnchenstücke anbraten","content":"Die übrigen 20 g Öl in einer großen Pfanne bei mittlerer Hitze erwärmen. Hähnchen mit den bereitgestellten 3 g Salz und 0,25 g Pfeffer würzen. Die 4 Stücke ohne Gedränge einlegen und ungefähr 4 Minuten je Seite, insgesamt etwa 8 Minuten, anbraten. Hitze so regeln, dass sie bräunen, ohne zu verbrennen. Noch keinen Honig und keine Sauce zugeben; die Mitte ist nicht automatisch gar.","image_alt":"Vier Hähnchenbrüste bräunen in einer großen Pfanne ohne Sauce und Spargel","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-04.webp"},{"title":"In der Sauce fertig garen und Temperatur prüfen","content":"Hitze reduzieren, die gesamte saubere Sauce aus Schritt 2 zugeben und etwa 6–8 Minuten sanft köcheln, dabei das Hähnchen wenden. Dickt sie zu früh ein, Hitze weiter reduzieren und kurz abdecken; Zucker nicht dunkel werden oder verbrennen lassen. Jedes Stück mit sauberer Sonde in der dicksten Mitte messen, ohne die Pfanne zu berühren: mindestens 74°C sind nötig. Bei niedrigerer Temperatur sanft weitergaren und erneut messen. Sauce soll flüssig und leicht glänzend bleiben, nicht wie dicker Karamell.","image_alt":"Gegarte Hähnchenbrüste mit leichter Zitronen-Honig-Sauce in der Pfanne","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-05.webp"},{"title":"Ruhen lassen, servieren und sicher aufbewahren","content":"Hähnchen auf eine saubere Platte geben und 5 Minuten ruhen lassen. In 4 Portionen aufteilen, Spargel und gesamte Sauce verteilen und saubere Geräte verwenden. Reste in flache Behälter geben und bei 4°C oder kälter innerhalb von 2 Stunden kühlen, beziehungsweise 1 Stunde bei Umgebungstemperatur über 32°C. Vorgeschlagen wird Verbrauch innerhalb von 3 Tagen; die Portion nur einmal auf 74°C im Kern erhitzen. Gegartes Hähnchen nicht auf den Teller legen, auf dem es roh lag.","image_alt":"Eine Hähnchenbrust mit Zitronen-Honig-Sauce neben geröstetem Spargel auf einem Teller","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-06.webp"}],"notes":"Honig eignet sich nicht für Kinder unter 12 Monaten. Allergene verpackter Produkte prüfen und Hähnchen ohne zugesetzte Salzlake verwenden, um die Berechnung anzunähern. Senf, Sojasauce, Butter, Brühe und weitere Beilagen sind nicht enthalten. Weißer Spargel kann bei gleichem Gewicht verwendet werden; Schälen und Garzeit anpassen, Ergebnis und Nährwerte ändern sich. Süßungsmittel sind kein gleichwertiger Ersatz für Honig: Konsistenz, Geschmack und Reduktion unterscheiden sich. Berechnet wird der Saft als essbarer Anteil; Zitronenscheiben und Kräuter kommen nicht ins Gericht. Spargel nach Entfernen harter Enden wiegen. Nährwerte zählen die gesamte Sauce und das Öl, geteilt durch 4; bleibt etwas in der Pfanne, kann die tatsächliche Aufnahme geringer sein. Einfrieren und Verwendung älterer Reste sind hier nicht geprüft.","nutrition":{"fat_g":13,"calories":372.9,"saturated_fat_g":2.2,"sodium_mg":482,"protein_g":48.5,"sugar_g":11.3,"carbs_g":15.7,"fiber_g":3.3,"estimated":true,"serving_size":"1 von 4 vorgeschlagenen Portionen","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Acht USDA-Datensätze anhand der FDC-ID im offiziellen Archiv geprüft. Rohe essbare Gewichte addiert und durch 4 geteilt; gesamte Sauce, Öl und Würzung gezählt.60 ml Trinkwasser liefern keine Energie und sind nicht Teil der acht Inputs. Nährstoffverluste und exakte Verteilung nach dem Garen werden nicht berechnet.","note":"Schätzung, keine Analyse des gegarten Gerichts. Salzlake im Fleisch, Honigsorte, Verluste und tatsächliche Portionen verändern die Werte; Mengen, Zeiten und Ausbeute sind noch nicht in der Küche geprüft.","inputs":[{"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120,"saturated_fat_g":0.563,"sodium_mg":45,"protein_g":22.5,"sugar_g":0,"carbs_g":0,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients","ingredient":"rohe Hähnchenbrust ohne Haut und Knochen","edible_grams":800},{"fdc_id":168389,"fdc_description":"Asparagus, raw","per_100g":{"saturated_fat_g":0.04,"protein_g":2.2,"sugar_g":1.88,"sodium_mg":2,"carbs_g":3.88,"calories":20,"fiber_g":2.1,"fat_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168389/nutrients","ingredient":"grüner Spargel, nach dem Putzen gewogen","edible_grams":600},{"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients","ingredient":"frisch gepresster Zitronensaft","edible_grams":40},{"fdc_id":169640,"fdc_description":"Honey","per_100g":{"saturated_fat_g":0,"protein_g":0.3,"fiber_g":0.2,"sodium_mg":4,"fat_g":0,"carbs_g":82.4,"calories":304,"sugar_g":82.1},"source_url":"https://fdc.nal.usda.gov/food-details/169640/nutrients","ingredient":"Honig","edible_grams":40},{"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"fat_g":100,"carbs_g":0,"calories":884,"sodium_mg":2,"protein_g":0,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients","ingredient":"Olivenöl","edible_grams":30},{"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.1,"calories":149,"sugar_g":1,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients","ingredient":"Knoblauch","edible_grams":10},{"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38800,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients","ingredient":"feines Salz","edible_grams":4},{"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":64,"calories":251,"protein_g":10.4,"fiber_g":25.3,"sodium_mg":20,"saturated_fat_g":1.39},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients","ingredient":"gemahlener schwarzer Pfeffer","edible_grams":0.5}]},"image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","gallery":[{"url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","alt":"Hähnchenbrust mit Zitronen-Honig-Sauce und geröstetem Spargel"}],"seo":{"title":"Zitronen-Honig-Hähnchen mit Spargel | Manual de Cocina","description":"Hähnchen in Zitronen-Honig-Knoblauch-Sauce für 4 mit geröstetem Spargel. Erst anbraten, dann Sauce zugeben und jedes Stück auf 74°C prüfen.","image_alt":"Hähnchenbrust mit Zitronen-Honig-Sauce und geröstetem Spargel","image_variants":["/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-1x1.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-4x3.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-16x9.webp"],"faq":[{"q":"Wie verhindere ich, dass Honig verbrennt?","a":"Hähnchen ohne Honig anbraten und Sauce nach Reduzieren der Hitze zugeben. Sanft köcheln und kurz abdecken, wenn die Sauce einkocht, bevor das Fleisch 74°C erreicht. Keine dunkle, dicke Sauce anstreben."},{"q":"Darf Spargel mit rohem Hähnchen rösten?","a":"Hier wird beides getrennt gegart. Spargel braucht eine andere Zeit und darf keine rohen Hähnchensäfte erhalten, wenn er früher herausgenommen wird. Ein sauberes Blech für die Beilage verwenden."},{"q":"Wie bewahre ich Reste auf und wärme sie auf?","a":"In flachen Behältern innerhalb von 2 Stunden kühlen, bei mehr als 32°C innerhalb von 1 Stunde, auf 4°C oder kälter. Vorgeschlagen sind 3 Tage Verbrauchsfrist und einmaliges Erhitzen auf 74°C im Kern."}]},"published":false,"editorial_status":"draft","content_html":"<p>Hähnchenbrüste werden in der Pfanne angebraten und anschließend in Zitronen-Honig-Knoblauch-Sauce fertig gegart. Grüner Spargel wird separat geröstet. Honig kommt erst nach dem Anbraten bei milder Hitze hinzu, damit er weniger leicht verbrennt. Die historische Identität und URL bleiben erhalten.</p><p>Vorgeschlagen sind 4 Portionen mit je einem Stück Hähnchen und einem Viertel von Spargel und Sauce. Geschätzt werden 15 Minuten Vorbereitung,25 Minuten teilweise paralleles Garen und 5 Minuten Ruhezeit: insgesamt 45 Minuten. Mengen, Zeiten und Ausbeute sind noch nicht in der Küche erprobt. Jedes Stück muss 74°C erreichen; Farbe und Zeit beweisen keine sichere Garung.</p>"},{"id":"32dbe096-a5e6-5993-9319-95287ada4d49","recipe_group_id":"ceed8c90-4245-4396-9095-d1d858d397ac","language":"en","slug":"delicious-lemon-and-honey-chicken-recipe-with-roasted-asparagus-2","public_path":"/en/delicious-lemon-and-honey-chicken-recipe-with-roasted-asparagus-2","source_url":null,"title":"Lemon and honey chicken with roasted asparagus","excerpt":"Chicken breasts with lemon, honey and garlic sauce and separately roasted asparagus. A proposed recipe for 4, with a 74°C temperature check.","summary":"Chicken breasts are browned in a skillet, then finished in a lemon, honey and garlic sauce, with green asparagus roasted separately. Honey is added after browning, over gentle heat, to reduce the risk of burning. The recipe preserves its historical identity and URL.\n\nThe proposal makes 4 servings, each with one chicken piece and a quarter of the asparagus and sauce. Allow an estimated 15 minutes preparation,25 cooking with parallel tasks and 5 resting:45 in total. Quantities, times and yield await kitchen testing. Check 74°C in every piece; colour and time do not certify doneness.","category":"Main dishes","category_slug":"platos-principales","difficulty":"Easy","course":"Main course","cuisine":"Home cooking","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["lemon chicken","honey chicken","roasted asparagus","chicken breasts in sauce"],"ingredients":[{"name":"raw boneless skinless chicken breast","amount":"800","unit":"g","group":"Chicken"},{"name":"green asparagus, weighed after trimming","amount":"600","unit":"g","group":"Side dish"},{"name":"freshly squeezed lemon juice","amount":"40","unit":"g","group":"Sauce"},{"name":"honey","amount":"40","unit":"g","group":"Sauce"},{"name":"olive oil","amount":"30","unit":"g","group":"Cooking and seasoning"},{"name":"garlic","amount":"10","unit":"g","group":"Sauce"},{"name":"fine salt","amount":"4","unit":"g","group":"Cooking and seasoning"},{"name":"ground black pepper","amount":"0.5","unit":"g","group":"Cooking and seasoning"},{"name":"drinking water","amount":"60","unit":"ml","group":"Sauce"}],"steps":[{"title":"Prepare the chicken and asparagus","content":"Preheat a conventional oven to 210°C, without fan. Wash the asparagus, trim woody bases and weigh 600 g after trimming; dry well. On a separate board prepare 4 chicken breast pieces totalling 800 g, about 200 g each, with an even thickness of 1.5–2 cm; butterfly thicker pieces if needed. Do not wash raw chicken. Keep raw and cooked utensils separate. Reserve 3 g salt and 0.25 g pepper for chicken, and 1 g salt and 0.25 g pepper for asparagus.","image_alt":"Clean asparagus on one board and four raw chicken breasts on another separate board","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-01.webp"},{"title":"Mix the sauce in a clean bowl","content":"Combine 40 g lemon juice,40 g honey,10 g chopped garlic and 60 ml drinking water. Stir until the honey dissolves. Keep this sauce in a clean bowl and prevent contact with raw chicken; it is not a marinade and juices from the raw-chicken plate are not reused.","image_alt":"Lemon, honey and garlic sauce being mixed in a bowl without contact with raw chicken","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-02.webp"},{"title":"Roast the asparagus separately","content":"Spread asparagus in a single layer on a tray with 10 g of the oil,1 g salt and 0.25 g pepper. Roast at 210°C for about 12–18 minutes, turning after 8 minutes, until tender with some bite and lightly browned tips. Thickness changes the timing. Do this while cooking chicken; if finished first, keep briefly covered while finishing the sauce. Do not put raw chicken on this tray.","image_alt":"Roasted green asparagus in a single layer on a tray without chicken","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-03.webp"},{"title":"Brown the four chicken pieces","content":"Heat the remaining 20 g oil in a wide skillet over medium heat. Season chicken with the reserved 3 g salt and 0.25 g pepper. Place the 4 pieces without crowding and brown for about 4 minutes per side, approximately 8 minutes total. Adjust heat to brown without burning. Do not add honey or sauce yet, and do not assume the centre is cooked.","image_alt":"Four chicken breasts browning in a wide skillet without sauce or asparagus","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-04.webp"},{"title":"Finish with sauce and check temperature","content":"Lower the heat, add all the clean sauce from step 2 and simmer gently for about 6–8 minutes, turning chicken to coat. If it thickens too early, lower heat further and cover briefly; do not let sugar darken or burn. Check each piece with a clean probe in the thickest centre, without touching the skillet: it must reach at least 74°C. If lower, continue cooking gently and measure again. Sauce should be fluid and lightly glossy, not thick caramel.","image_alt":"Cooked chicken breasts coated with light lemon and honey sauce in a skillet","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-05.webp"},{"title":"Rest, serve and store safely","content":"Transfer chicken to a clean dish and rest 5 minutes. Divide into 4 servings and distribute asparagus and all the sauce; use clean utensils. For storage, put leftovers in shallow containers and refrigerate at 4°C or below within 2 hours, or 1 hour if ambient temperature exceeds 32°C. The proposal is to consume within 3 days and reheat each portion only once to 74°C at its centre. Do not put cooked chicken on the plate that held it raw.","image_alt":"One chicken breast with lemon and honey sauce beside roasted asparagus on a plate","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-06.webp"}],"notes":"Honey is unsuitable for children under 12 months. Check packaged-product allergens and use chicken without added brine to approximate the calculation. No mustard, soy sauce, butter, stock or extra sides are included. White asparagus can replace green at the same weight, with peeling and cooking adjusted; results and nutrients change. Sweeteners are not equivalent substitutes for honey: texture, taste and reduction differ. Juice is the edible part counted; lemon slices and herbs are not added to the dish. Weigh asparagus after removing woody bases. Nutrition counts all sauce and oil shared between 4; if some remains in the skillet, actual intake may be lower. Freezing and use of previous leftovers have not been validated here.","nutrition":{"fat_g":13,"calories":372.9,"saturated_fat_g":2.2,"sodium_mg":482,"protein_g":48.5,"sugar_g":11.3,"carbs_g":15.7,"fiber_g":3.3,"estimated":true,"serving_size":"1 of 4 proposed servings","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Eight USDA records verified by FDC ID in the official archive. Raw edible weights summed and divided by 4; all sauce, oil and seasoning are counted. The 60 ml drinking water contributes no energy and is excluded from the eight inputs. Nutrient losses and exact distribution after cooking are not calculated.","note":"Estimate, not an analysis of the cooked dish. Chicken brine, honey type, losses and actual portions alter the figures; quantities, times and yield await kitchen testing.","inputs":[{"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120,"saturated_fat_g":0.563,"sodium_mg":45,"protein_g":22.5,"sugar_g":0,"carbs_g":0,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients","ingredient":"raw boneless skinless chicken breast","edible_grams":800},{"fdc_id":168389,"fdc_description":"Asparagus, raw","per_100g":{"saturated_fat_g":0.04,"protein_g":2.2,"sugar_g":1.88,"sodium_mg":2,"carbs_g":3.88,"calories":20,"fiber_g":2.1,"fat_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168389/nutrients","ingredient":"green asparagus, weighed after trimming","edible_grams":600},{"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients","ingredient":"freshly squeezed lemon juice","edible_grams":40},{"fdc_id":169640,"fdc_description":"Honey","per_100g":{"saturated_fat_g":0,"protein_g":0.3,"fiber_g":0.2,"sodium_mg":4,"fat_g":0,"carbs_g":82.4,"calories":304,"sugar_g":82.1},"source_url":"https://fdc.nal.usda.gov/food-details/169640/nutrients","ingredient":"honey","edible_grams":40},{"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"fat_g":100,"carbs_g":0,"calories":884,"sodium_mg":2,"protein_g":0,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients","ingredient":"olive oil","edible_grams":30},{"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.1,"calories":149,"sugar_g":1,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients","ingredient":"garlic","edible_grams":10},{"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38800,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients","ingredient":"fine salt","edible_grams":4},{"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":64,"calories":251,"protein_g":10.4,"fiber_g":25.3,"sodium_mg":20,"saturated_fat_g":1.39},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients","ingredient":"ground black pepper","edible_grams":0.5}]},"image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","gallery":[{"url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","alt":"Chicken breast with lemon and honey sauce beside roasted asparagus"}],"seo":{"title":"Lemon honey chicken with asparagus | Manual de Cocina","description":"Chicken with lemon, honey and garlic sauce for 4, with roasted asparagus. Brown first, add sauce later and check 74°C in every piece.","image_alt":"Chicken breast with lemon and honey sauce beside roasted asparagus","image_variants":["/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-1x1.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-4x3.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-16x9.webp"],"faq":[{"q":"How can I stop honey burning?","a":"Brown chicken without honey and add sauce after lowering the heat. Keep a gentle simmer and cover briefly if sauce reduces before chicken reaches 74°C. Do not aim for a dark, thick sauce."},{"q":"Can I roast asparagus with raw chicken?","a":"This recipe cooks them separately. Asparagus has a different timing and must not receive raw chicken juices if it will be removed sooner. Use a clean tray for the side dish."},{"q":"How should I store and reheat leftovers?","a":"Refrigerate in shallow containers within 2 hours, or 1 hour above 32°C, at 4°C or below. Consume within the proposed 3 days and reheat once to 74°C in the centre."}]},"published":false,"editorial_status":"draft","content_html":"<p>Chicken breasts are browned in a skillet, then finished in a lemon, honey and garlic sauce, with green asparagus roasted separately. Honey is added after browning, over gentle heat, to reduce the risk of burning. The recipe preserves its historical identity and URL.</p><p>The proposal makes 4 servings, each with one chicken piece and a quarter of the asparagus and sauce. Allow an estimated 15 minutes preparation,25 cooking with parallel tasks and 5 resting:45 in total. Quantities, times and yield await kitchen testing. Check 74°C in every piece; colour and time do not certify doneness.</p>"},{"id":"5368bb57-0665-577a-b036-23e0de5be2c4","recipe_group_id":"ceed8c90-4245-4396-9095-d1d858d397ac","language":"fr","slug":"delicieuse-recette-de-poulet-au-citron-et-miel-avec-asperges-roties","public_path":"/fr/delicieuse-recette-de-poulet-au-citron-et-miel-avec-asperges-roties","source_url":null,"title":"Poulet au citron et au miel, asperges rôties","excerpt":"Blancs de poulet en sauce citron, miel et ail, accompagnés d’asperges rôties séparément. Proposition pour 4 avec contrôle à 74°C.","summary":"Les blancs de poulet sont dorés à la poêle puis terminés dans une sauce au citron, au miel et à l’ail. Les asperges vertes rôtissent séparément. Le miel est ajouté après coloration, à feu doux, pour limiter le risque de brûler. L’identité et l’URL historiques sont conservées.\n\nLa proposition donne 4 portions, chacune avec un morceau de poulet et un quart des asperges et de la sauce. Compter environ 15 minutes de préparation,25 de cuisson avec des tâches parallèles et 5 de repos, soit 45 minutes. Quantités, temps et rendement restent à tester en cuisine. Vérifier 74°C dans chaque morceau; couleur et durée ne certifient pas la cuisson.","category":"Plats principaux","category_slug":"platos-principales","difficulty":"Facile","course":"Plat principal","cuisine":"Cuisine maison","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["poulet au citron","poulet au miel","asperges rôties","blancs de poulet en sauce"],"ingredients":[{"name":"blanc de poulet cru sans peau ni os","amount":"800","unit":"g","group":"Poulet"},{"name":"asperges vertes, pesées après parage","amount":"600","unit":"g","group":"Accompagnement"},{"name":"jus de citron fraîchement pressé","amount":"40","unit":"g","group":"Sauce"},{"name":"miel","amount":"40","unit":"g","group":"Sauce"},{"name":"huile d’olive","amount":"30","unit":"g","group":"Cuisson et assaisonnement"},{"name":"ail","amount":"10","unit":"g","group":"Sauce"},{"name":"sel fin","amount":"4","unit":"g","group":"Cuisson et assaisonnement"},{"name":"poivre noir moulu","amount":"0.5","unit":"g","group":"Cuisson et assaisonnement"},{"name":"eau potable","amount":"60","unit":"ml","group":"Sauce"}],"steps":[{"title":"Préparer le poulet et les asperges","content":"Préchauffer le four à 210°C, chaleur haut et bas sans ventilation. Laver les asperges, retirer les bases dures et peser 600 g nettoyés; bien sécher. Sur une autre planche préparer 4 morceaux de blanc totalisant 800 g, environ 200 g chacun, d’épaisseur régulière de 1,5–2 cm; ouvrir les plus épais si nécessaire. Ne pas laver le poulet cru. Séparer les ustensiles du cru et du cuit. Réserver 3 g de sel et 0,25 g de poivre pour le poulet, puis 1 g de sel et 0,25 g de poivre pour les asperges.","image_alt":"Asperges propres sur une planche et quatre blancs de poulet crus sur une autre planche séparée","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-01.webp"},{"title":"Mélanger la sauce dans un récipient propre","content":"Mélanger 40 g de jus de citron,40 g de miel,10 g d’ail haché et 60 ml d’eau potable. Remuer pour dissoudre le miel. Garder cette sauce dans un récipient propre, sans contact avec le poulet cru. Ce n’est pas une marinade et les jus du plat de poulet cru ne sont pas réutilisés.","image_alt":"Sauce citron, miel et ail mélangée dans un bol sans contact avec du poulet cru","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-02.webp"},{"title":"Rôtir les asperges séparément","content":"Répartir les asperges en une seule couche sur une plaque avec 10 g de l’huile,1 g de sel et 0,25 g de poivre. Rôtir à 210°C environ 12–18 minutes, en les retournant après 8 minutes, jusqu’à ce qu’elles soient tendres mais encore fermes, avec des pointes légèrement dorées. L’épaisseur modifie le temps. Faire cette tâche pendant la cuisson du poulet; si elles finissent avant, les couvrir brièvement le temps de terminer la sauce. Ne pas déposer de poulet cru sur cette plaque.","image_alt":"Asperges vertes rôties en une couche sur une plaque sans poulet","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-03.webp"},{"title":"Dorer les quatre morceaux de poulet","content":"Chauffer les 20 g d’huile restants dans une grande poêle à feu moyen. Assaisonner le poulet avec les 3 g de sel et 0,25 g de poivre réservés. Placer les 4 morceaux sans les entasser et dorer environ 4 minutes par face, soit 8 minutes au total. Régler le feu pour colorer sans brûler. Ne pas ajouter miel ou sauce à ce stade et ne pas considérer le centre comme déjà cuit.","image_alt":"Quatre blancs de poulet dorent dans une grande poêle sans sauce ni asperges","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-04.webp"},{"title":"Terminer dans la sauce et vérifier la température","content":"Baisser le feu, ajouter toute la sauce propre de l’étape 2 et laisser frémir environ 6–8 minutes en retournant le poulet. Si elle épaissit trop tôt, réduire encore le feu et couvrir brièvement; ne pas laisser le sucre foncer ou brûler. Mesurer chaque morceau avec une sonde propre au centre le plus épais, sans toucher la poêle: il doit atteindre au moins 74°C. Sinon, prolonger doucement et mesurer de nouveau. La sauce doit rester fluide et légèrement brillante, pas devenir un caramel épais.","image_alt":"Blancs cuits nappés de sauce légère au citron et au miel dans une poêle","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-05.webp"},{"title":"Laisser reposer, servir et conserver","content":"Transférer le poulet sur un plat propre et laisser reposer 5 minutes. Diviser en 4 portions et répartir asperges et totalité de la sauce avec des ustensiles propres. Pour conserver, placer les restes dans des récipients peu profonds et réfrigérer à 4°C ou moins dans les 2 heures, ou 1 heure si l’ambiance dépasse 32°C. Il est proposé de consommer dans les 3 jours et de réchauffer chaque portion une seule fois à 74°C au centre. Ne pas remettre le poulet cuit dans le plat ayant contenu le cru.","image_alt":"Un blanc en sauce citron et miel avec des asperges rôties dans une assiette","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-06.webp"}],"notes":"Le miel ne convient pas aux enfants de moins de 12 mois. Vérifier les allergènes des produits emballés et choisir du poulet sans saumure ajoutée pour approcher le calcul. Moutarde, sauce soja, beurre, bouillon et accompagnements supplémentaires sont exclus. On peut utiliser le même poids d’asperges blanches en ajustant épluchage et cuisson; résultat et nutriments changent. Les édulcorants ne remplacent pas le miel à l’identique: texture, goût et réduction diffèrent. Le jus est la partie comestible comptée; aucune rondelle de citron ni herbe n’est ajoutée. Peser les asperges après retrait des bases dures. La nutrition compte toute la sauce et l’huile réparties entre 4; si une partie reste dans la poêle, l’apport réel peut être inférieur. Congélation et utilisation de restes antérieurs ne sont pas validées ici.","nutrition":{"fat_g":13,"calories":372.9,"saturated_fat_g":2.2,"sodium_mg":482,"protein_g":48.5,"sugar_g":11.3,"carbs_g":15.7,"fiber_g":3.3,"estimated":true,"serving_size":"1 des 4 portions proposées","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Huit fiches USDA vérifiées par identifiant FDC dans l’archive officielle. Poids comestibles crus additionnés puis divisés par 4; toute la sauce, l’huile et l’assaisonnement sont comptés. Les 60 ml d’eau potable n’apportent pas d’énergie et sont exclus des huit inputs. Pertes de nutriments et répartition exacte après cuisson non calculées.","note":"Estimation, pas une analyse du plat cuisiné. Saumure du poulet, type de miel, pertes et portions réelles modifient les chiffres; quantités, temps et rendement restent à tester en cuisine.","inputs":[{"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120,"saturated_fat_g":0.563,"sodium_mg":45,"protein_g":22.5,"sugar_g":0,"carbs_g":0,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients","ingredient":"blanc de poulet cru sans peau ni os","edible_grams":800},{"fdc_id":168389,"fdc_description":"Asparagus, raw","per_100g":{"saturated_fat_g":0.04,"protein_g":2.2,"sugar_g":1.88,"sodium_mg":2,"carbs_g":3.88,"calories":20,"fiber_g":2.1,"fat_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168389/nutrients","ingredient":"asperges vertes, pesées après parage","edible_grams":600},{"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients","ingredient":"jus de citron fraîchement pressé","edible_grams":40},{"fdc_id":169640,"fdc_description":"Honey","per_100g":{"saturated_fat_g":0,"protein_g":0.3,"fiber_g":0.2,"sodium_mg":4,"fat_g":0,"carbs_g":82.4,"calories":304,"sugar_g":82.1},"source_url":"https://fdc.nal.usda.gov/food-details/169640/nutrients","ingredient":"miel","edible_grams":40},{"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"fat_g":100,"carbs_g":0,"calories":884,"sodium_mg":2,"protein_g":0,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients","ingredient":"huile d’olive","edible_grams":30},{"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.1,"calories":149,"sugar_g":1,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients","ingredient":"ail","edible_grams":10},{"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38800,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients","ingredient":"sel fin","edible_grams":4},{"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":64,"calories":251,"protein_g":10.4,"fiber_g":25.3,"sodium_mg":20,"saturated_fat_g":1.39},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients","ingredient":"poivre noir moulu","edible_grams":0.5}]},"image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","gallery":[{"url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","alt":"Blanc de poulet au citron et au miel accompagné d’asperges rôties"}],"seo":{"title":"Poulet citron miel et asperges | Manual de Cocina","description":"Poulet en sauce citron, miel et ail pour 4, avec asperges rôties. Dorer d’abord, ajouter la sauce ensuite et vérifier 74°C dans chaque morceau.","image_alt":"Blanc de poulet au citron et au miel accompagné d’asperges rôties","image_variants":["/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-1x1.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-4x3.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-16x9.webp"],"faq":[{"q":"Comment éviter de brûler le miel?","a":"Dorer le poulet sans miel et ajouter la sauce après avoir baissé le feu. Garder un frémissement doux et couvrir brièvement si la sauce réduit avant que le poulet atteigne 74°C. Ne pas rechercher une sauce foncée et épaisse."},{"q":"Peut-on rôtir les asperges avec le poulet cru?","a":"Cette fiche les cuit séparément. Les asperges ont un autre temps et ne doivent pas recevoir de jus crus de poulet si elles sont retirées plus tôt. Utiliser une plaque propre pour l’accompagnement."},{"q":"Comment conserver et réchauffer les restes?","a":"Réfrigérer en récipients peu profonds dans les 2 heures, ou 1 heure au-dessus de 32°C, à 4°C ou moins. Consommer dans les 3 jours proposés et réchauffer une fois à 74°C au centre."}]},"published":false,"editorial_status":"draft","content_html":"<p>Les blancs de poulet sont dorés à la poêle puis terminés dans une sauce au citron, au miel et à l’ail. Les asperges vertes rôtissent séparément. Le miel est ajouté après coloration, à feu doux, pour limiter le risque de brûler. L’identité et l’URL historiques sont conservées.</p><p>La proposition donne 4 portions, chacune avec un morceau de poulet et un quart des asperges et de la sauce. Compter environ 15 minutes de préparation,25 de cuisson avec des tâches parallèles et 5 de repos, soit 45 minutes. Quantités, temps et rendement restent à tester en cuisine. Vérifier 74°C dans chaque morceau; couleur et durée ne certifient pas la cuisson.</p>"},{"id":"b44de411-6e7e-5f03-8fa2-c3a24d8aa91a","recipe_group_id":"ceed8c90-4245-4396-9095-d1d858d397ac","language":"it","slug":"deliziosa-ricetta-di-pollo-al-limone-e-miele-con-asparagi-arrostiti-2","public_path":"/it/deliziosa-ricetta-di-pollo-al-limone-e-miele-con-asparagi-arrostiti-2","source_url":null,"title":"Pollo al limone e miele con asparagi arrostiti","excerpt":"Petti di pollo con salsa di limone, miele e aglio e asparagi arrostiti separatamente. Proposta per 4 con controllo a 74°C.","summary":"I petti di pollo vengono rosolati in padella e poi terminati in una salsa di limone, miele e aglio, con asparagi verdi arrostiti separatamente. Il miele entra dopo la rosolatura, a fuoco dolce, per ridurre il rischio di bruciarlo. Identità e URL storici vengono conservati.\n\nLa proposta dà 4 porzioni, ciascuna con un pezzo di pollo e un quarto degli asparagi e della salsa. Si stimano 15 minuti di preparazione,25 di cottura con attività in parallelo e 5 di riposo:45 in totale. Quantità, tempi e resa attendono una prova in cucina. Verifica 74°C in ogni pezzo; colore e tempo non certificano la cottura.","category":"Secondi piatti","category_slug":"platos-principales","difficulty":"Facile","course":"Secondo piatto","cuisine":"Cucina casalinga","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["pollo al limone","pollo al miele","asparagi arrostiti","petto di pollo in salsa"],"ingredients":[{"name":"petto di pollo crudo senza pelle né ossa","amount":"800","unit":"g","group":"Pollo"},{"name":"asparagi verdi, pesati dopo la pulizia","amount":"600","unit":"g","group":"Contorno"},{"name":"succo di limone appena spremuto","amount":"40","unit":"g","group":"Salsa"},{"name":"miele","amount":"40","unit":"g","group":"Salsa"},{"name":"olio d’oliva","amount":"30","unit":"g","group":"Cottura e condimento"},{"name":"aglio","amount":"10","unit":"g","group":"Salsa"},{"name":"sale fino","amount":"4","unit":"g","group":"Cottura e condimento"},{"name":"pepe nero macinato","amount":"0.5","unit":"g","group":"Cottura e condimento"},{"name":"acqua potabile","amount":"60","unit":"ml","group":"Salsa"}],"steps":[{"title":"Prepara pollo e asparagi","content":"Preriscalda il forno a 210°C statico, senza ventola. Lava gli asparagi, elimina le basi dure e pesa 600 g già puliti; asciuga bene. Su un tagliere separato prepara 4 pezzi di petto per un totale di 800 g, circa 200 g ciascuno, con spessore uniforme di 1,5–2 cm; apri quelli più spessi se serve. Non lavare il pollo crudo. Separa utensili per crudo e cotto. Riserva 3 g di sale e 0,25 g di pepe per il pollo, e 1 g di sale e 0,25 g di pepe per gli asparagi.","image_alt":"Asparagi puliti su un tagliere e quattro petti crudi su un altro tagliere separato","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-01.webp"},{"title":"Mescola la salsa in un recipiente pulito","content":"Mescola 40 g di succo di limone,40 g di miele,10 g di aglio tritato e 60 ml di acqua potabile. Sciogli il miele mescolando. Conserva la salsa in un recipiente pulito e impedisci il contatto con pollo crudo; non è una marinata e i liquidi del piatto del pollo crudo non vengono riutilizzati.","image_alt":"Salsa di limone, miele e aglio mescolata in una ciotola senza contatto con pollo crudo","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-02.webp"},{"title":"Arrostisci gli asparagi separatamente","content":"Distribuisci gli asparagi in un solo strato su una teglia con 10 g dell’olio,1 g di sale e 0,25 g di pepe. Cuoci a 210°C per circa 12–18 minuti, girando dopo 8 minuti, finché sono teneri ma ancora consistenti, con punte leggermente dorate. Lo spessore modifica il tempo. Procedi mentre cuoci il pollo; se finiscono prima, tienili brevemente coperti mentre termini la salsa. Non mettere pollo crudo su questa teglia.","image_alt":"Asparagi verdi arrostiti in un solo strato su una teglia senza pollo","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-03.webp"},{"title":"Rosola i quattro pezzi di pollo","content":"Scalda i 20 g di olio restanti in una padella ampia a fuoco medio. Condisci il pollo con i 3 g di sale e 0,25 g di pepe riservati. Disponi i 4 pezzi senza affollarli e rosola circa 4 minuti per lato, approssimativamente 8 minuti totali. Regola il fuoco per dorare senza bruciare. Non aggiungere ancora miele o salsa e non considerare già cotto il centro.","image_alt":"Quattro petti di pollo rosolano in una padella ampia senza salsa né asparagi","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-04.webp"},{"title":"Termina con la salsa e controlla la temperatura","content":"Abbassa il fuoco, aggiungi tutta la salsa pulita del passaggio 2 e fai sobbollire dolcemente circa 6–8 minuti, girando il pollo. Se si addensa troppo presto, riduci ancora il fuoco e copri brevemente; non lasciare scurire o bruciare lo zucchero. Misura ogni pezzo con una sonda pulita al centro più spesso, senza toccare la padella: deve raggiungere almeno 74°C. Se non ci arriva, prolunga a fuoco dolce e misura ancora. La salsa deve essere fluida e leggermente lucida, non un caramello denso.","image_alt":"Petti cotti ricoperti di salsa leggera al limone e miele in padella","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-05.webp"},{"title":"Riposa, servi e conserva in sicurezza","content":"Trasferisci il pollo in un piatto pulito e lascia riposare 5 minuti. Dividi in 4 porzioni e distribuisci asparagi e tutta la salsa con utensili puliti. Per conservare, metti gli avanzi in contenitori bassi e refrigera a 4°C o meno entro 2 ore, oppure 1 ora se l’ambiente supera 32°C. Si propone di consumare entro 3 giorni e riscaldare ogni porzione una sola volta fino a 74°C al centro. Non mettere pollo cotto nel piatto che conteneva quello crudo.","image_alt":"Un petto con salsa al limone e miele accanto ad asparagi arrostiti nel piatto","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-06.webp"}],"notes":"Il miele non è adatto a bambini sotto 12 mesi. Controlla gli allergeni dei prodotti confezionati e usa pollo senza salamoia aggiunta per avvicinarti al calcolo. Non sono inclusi senape, salsa di soia, burro, brodo o contorni extra. Puoi usare lo stesso peso di asparagi bianchi adattando pelatura e cottura; risultato e nutrienti cambiano. I dolcificanti non equivalgono al miele: consistenza, gusto e riduzione sono diversi. La parte commestibile conteggiata è il succo; non si aggiungono fettine di limone o erbe. Pesa gli asparagi dopo aver tolto le basi dure. La nutrizione conta tutta la salsa e l’olio divisi tra 4; se ne resta in padella, l’apporto reale può diminuire. Non sono stati validati qui congelamento e uso di avanzi precedenti.","nutrition":{"fat_g":13,"calories":372.9,"saturated_fat_g":2.2,"sodium_mg":482,"protein_g":48.5,"sugar_g":11.3,"carbs_g":15.7,"fiber_g":3.3,"estimated":true,"serving_size":"1 delle 4 porzioni proposte","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Otto schede USDA verificate per FDC ID nell’archivio ufficiale. Pesi commestibili crudi sommati e divisi per 4; conteggiati tutta la salsa, olio e condimento. I 60 ml di acqua potabile non danno energia e sono esclusi dagli otto inputs. Non si calcolano perdite di nutrienti o ripartizione esatta dopo la cottura.","note":"Stima, non analisi del piatto cotto. Salamoia nel pollo, tipo di miele, perdite e porzioni reali cambiano i valori; quantità, tempi e resa attendono prova in cucina.","inputs":[{"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120,"saturated_fat_g":0.563,"sodium_mg":45,"protein_g":22.5,"sugar_g":0,"carbs_g":0,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients","ingredient":"petto di pollo crudo senza pelle né ossa","edible_grams":800},{"fdc_id":168389,"fdc_description":"Asparagus, raw","per_100g":{"saturated_fat_g":0.04,"protein_g":2.2,"sugar_g":1.88,"sodium_mg":2,"carbs_g":3.88,"calories":20,"fiber_g":2.1,"fat_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168389/nutrients","ingredient":"asparagi verdi, pesati dopo la pulizia","edible_grams":600},{"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients","ingredient":"succo di limone appena spremuto","edible_grams":40},{"fdc_id":169640,"fdc_description":"Honey","per_100g":{"saturated_fat_g":0,"protein_g":0.3,"fiber_g":0.2,"sodium_mg":4,"fat_g":0,"carbs_g":82.4,"calories":304,"sugar_g":82.1},"source_url":"https://fdc.nal.usda.gov/food-details/169640/nutrients","ingredient":"miele","edible_grams":40},{"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"fat_g":100,"carbs_g":0,"calories":884,"sodium_mg":2,"protein_g":0,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients","ingredient":"olio d’oliva","edible_grams":30},{"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.1,"calories":149,"sugar_g":1,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients","ingredient":"aglio","edible_grams":10},{"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38800,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients","ingredient":"sale fino","edible_grams":4},{"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":64,"calories":251,"protein_g":10.4,"fiber_g":25.3,"sodium_mg":20,"saturated_fat_g":1.39},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients","ingredient":"pepe nero macinato","edible_grams":0.5}]},"image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","gallery":[{"url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","alt":"Petto di pollo al limone e miele con asparagi arrostiti"}],"seo":{"title":"Pollo limone e miele con asparagi | Manual de Cocina","description":"Pollo con salsa di limone, miele e aglio per 4 e asparagi arrostiti. Rosola prima, aggiungi poi la salsa e controlla 74°C in ogni pezzo.","image_alt":"Petto di pollo al limone e miele con asparagi arrostiti","image_variants":["/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-1x1.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-4x3.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-16x9.webp"],"faq":[{"q":"Come evito che il miele bruci?","a":"Rosola il pollo senza miele e aggiungi la salsa dopo aver abbassato il fuoco. Mantieni un sobbollore dolce e copri brevemente se la salsa si riduce prima che il pollo arrivi a 74°C. Non cercare una salsa scura e densa."},{"q":"Posso arrostire asparagi e pollo crudo insieme?","a":"Questa scheda li cuoce separatamente. Gli asparagi hanno un altro tempo e non devono ricevere liquidi crudi del pollo se vengono tolti prima. Usa una teglia pulita per il contorno."},{"q":"Come conservo e riscaldo gli avanzi?","a":"Refrigera in contenitori bassi entro 2 ore, o 1 ora sopra 32°C, a 4°C o meno. Consuma nei 3 giorni proposti e riscalda una volta a 74°C al centro."}]},"published":false,"editorial_status":"draft","content_html":"<p>I petti di pollo vengono rosolati in padella e poi terminati in una salsa di limone, miele e aglio, con asparagi verdi arrostiti separatamente. Il miele entra dopo la rosolatura, a fuoco dolce, per ridurre il rischio di bruciarlo. Identità e URL storici vengono conservati.</p><p>La proposta dà 4 porzioni, ciascuna con un pezzo di pollo e un quarto degli asparagi e della salsa. Si stimano 15 minuti di preparazione,25 di cottura con attività in parallelo e 5 di riposo:45 in totale. Quantità, tempi e resa attendono una prova in cucina. Verifica 74°C in ogni pezzo; colore e tempo non certificano la cottura.</p>"},{"id":"c5f3b8da-c6c3-5db1-9697-a0b956bc7a9e","recipe_group_id":"ceed8c90-4245-4396-9095-d1d858d397ac","language":"ja","slug":"おいしいレモンとはちみつチキンのレシピ、ロー","public_path":"/ja/おいしいレモンとはちみつチキンのレシピ、ロー","source_url":null,"title":"レモンとはちみつのチキンとローストアスパラガス","excerpt":"レモン、はちみつ、にんにくのソースで仕上げる鶏むね肉と、別に焼くアスパラガス。4人分の提案で、鶏肉は74°Cを確認します。","summary":"鶏むね肉をフライパンで焼き付け、レモン、はちみつ、にんにくのソースで火を通します。グリーンアスパラガスは別にオーブンで焼きます。はちみつは焼き付けた後に弱火で加え、焦げる危険を減らします。このレシピの歴史的な識別情報とURLを保持しています。\n\n提案量は4人分です。1人分は鶏肉1切れとアスパラガス、ソースそれぞれ全量の4分の1。下準備15分、並行作業を含む加熱25分、休ませる時間5分、合計45分を推定しています。分量、時間、出来上がり量は調理検証前の目安です。各切れの中心が74°Cに達したことを確認してください。色や時間だけで安全な加熱を判断しません。","category":"主菜","category_slug":"platos-principales","difficulty":"簡単","course":"主菜","cuisine":"家庭料理","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["レモンチキン","はちみつチキン","ローストアスパラガス","鶏むね肉のソース煮"],"ingredients":[{"name":"生の皮なし骨なし鶏むね肉","amount":"800","unit":"g","group":"鶏肉"},{"name":"グリーンアスパラガス、硬い根元を除いた重量","amount":"600","unit":"g","group":"付け合わせ"},{"name":"搾りたてのレモン汁","amount":"40","unit":"g","group":"ソース"},{"name":"はちみつ","amount":"40","unit":"g","group":"ソース"},{"name":"オリーブオイル","amount":"30","unit":"g","group":"加熱と味付け"},{"name":"にんにく","amount":"10","unit":"g","group":"ソース"},{"name":"細かい塩","amount":"4","unit":"g","group":"加熱と味付け"},{"name":"黒こしょう粉","amount":"0.5","unit":"g","group":"加熱と味付け"},{"name":"飲用水","amount":"60","unit":"ml","group":"ソース"}],"steps":[{"title":"鶏肉とアスパラガスを準備する","content":"オーブンをファンなしの上下加熱210°Cに予熱します。アスパラガスを洗い、硬い根元を切り落として600 gを量り、水気をよく拭きます。別のまな板で鶏むね肉を合計800 g、約200 gずつ4切れにし、厚さを1.5–2 cmにそろえます。厚いものは必要に応じて開きます。生の鶏肉は洗いません。生用と加熱後用の器具を分けます。鶏肉用に塩3 gとこしょう0.25 g、アスパラガス用に塩1 gとこしょう0.25 gを分けておきます。","image_alt":"清潔なアスパラガスと、別のまな板に置かれた生の鶏むね肉4切れ","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-01.webp"},{"title":"清潔な器でソースを混ぜる","content":"レモン汁40 g、はちみつ40 g、刻んだにんにく10 g、飲用水60 mlを混ぜ、はちみつを溶かします。ソースは清潔な器に入れ、生の鶏肉に触れさせません。漬け汁にはせず、生肉を置いた皿の肉汁も再使用しません。","image_alt":"生の鶏肉に触れず、器で混ぜるレモン、はちみつ、にんにくのソース","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-02.webp"},{"title":"アスパラガスを別に焼く","content":"天板にアスパラガスを重ならないように並べ、オイルのうち10 g、塩1 g、こしょう0.25 gを絡めます。210°Cで約12–18分焼き、8分経ったら裏返します。適度な歯ごたえを残して柔らかくなり、穂先が軽く色づくのが目安です。太さで時間は変わります。鶏肉と並行して焼き、先に焼けた場合はソースができるまで短時間覆っておきます。この天板に生の鶏肉を置きません。","image_alt":"鶏肉を載せず、天板に1層に並べて焼いたグリーンアスパラガス","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-03.webp"},{"title":"鶏肉4切れを焼き付ける","content":"大きなフライパンに残りのオイル20 gを入れ、中火にします。鶏肉に分けておいた塩3 gとこしょう0.25 gを振ります。4切れを詰め込まずに並べ、片面約4分、合計約8分焼き付けます。焦げないよう火力を調整します。まだはちみつやソースを加えず、中心まで火が通ったとは判断しません。","image_alt":"ソースやアスパラガスを加えず、フライパンで焼き付ける鶏むね肉4切れ","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-04.webp"},{"title":"ソースで仕上げ、温度を確認する","content":"火を弱め、手順2の清潔なソースを全量加えます。鶏肉を返して絡めながら約6–8分、穏やかに煮ます。早くとろみが付いたらさらに火を弱め、短時間ふたをします。糖分を濃く色づかせたり焦がしたりしません。清潔な温度計を各切れの最も厚い中心に差し、フライパンに触れないよう測ります。最低74°Cが必要です。足りなければ弱火で加熱を続け、再測定します。ソースは流れる程度で軽い艶があり、濃いカラメル状にはしません。","image_alt":"軽いレモンとはちみつのソースを絡めた加熱済みの鶏むね肉","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-05.webp"},{"title":"休ませて盛り付け、安全に保存する","content":"鶏肉を清潔な皿に取り出し、5分休ませます。4人分に分け、アスパラガスとソース全量を配り、清潔な器具で盛ります。残りは浅い容器に分け、2時間以内、室温が32°Cを超える場合は1時間以内に、4°C以下で冷蔵します。保存期間は3日以内を提案し、1人分ずつ中心が74°Cになるまで1回だけ再加熱します。生肉が入っていた皿に加熱済みの鶏肉を戻しません。","image_alt":"皿に盛ったレモンとはちみつのチキンとローストアスパラガス","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-06.webp"}],"notes":"はちみつは12か月未満の乳児には与えません。包装食品のアレルゲンを確認し、計算に近づけるには塩水を添加していない鶏肉を使います。マスタード、しょうゆ、バター、スープ、追加の付け合わせは含みません。同じ重量のホワイトアスパラガスに替える場合は皮むきと加熱を調整し、仕上がりと栄養値が変わります。甘味料ははちみつと同等の代用品ではなく、食感、味、煮詰まり方が異なります。計算する可食部はレモン汁で、レモンの輪切りやハーブは加えません。アスパラガスは硬い根元を除いてから量ります。栄養計算はソースとオイルを全量含み、4人分に分けています。フライパンに残れば実際の摂取量は少なくなる場合があります。冷凍や以前の残り物の利用は検証していません。","nutrition":{"fat_g":13,"calories":372.9,"saturated_fat_g":2.2,"sodium_mg":482,"protein_g":48.5,"sugar_g":11.3,"carbs_g":15.7,"fiber_g":3.3,"estimated":true,"serving_size":"提案量4人分のうち1人分","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"公式アーカイブの8件のUSDA食品データをFDC IDで確認。生の可食重量を合計して4で割り、ソース、オイル、調味料を全量計上します。飲用水60 mlはエネルギーを含まず、8件のinputsから除外します。加熱による栄養損失や正確な分配は計算しません。","note":"調理後の分析値ではなく推定値です。鶏肉への塩水添加、はちみつの種類、損失、実際の分配で数値は変わり、分量、時間、出来上がり量は調理検証前です。","inputs":[{"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120,"saturated_fat_g":0.563,"sodium_mg":45,"protein_g":22.5,"sugar_g":0,"carbs_g":0,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients","ingredient":"生の皮なし骨なし鶏むね肉","edible_grams":800},{"fdc_id":168389,"fdc_description":"Asparagus, raw","per_100g":{"saturated_fat_g":0.04,"protein_g":2.2,"sugar_g":1.88,"sodium_mg":2,"carbs_g":3.88,"calories":20,"fiber_g":2.1,"fat_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168389/nutrients","ingredient":"グリーンアスパラガス、硬い根元を除いた重量","edible_grams":600},{"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients","ingredient":"搾りたてのレモン汁","edible_grams":40},{"fdc_id":169640,"fdc_description":"Honey","per_100g":{"saturated_fat_g":0,"protein_g":0.3,"fiber_g":0.2,"sodium_mg":4,"fat_g":0,"carbs_g":82.4,"calories":304,"sugar_g":82.1},"source_url":"https://fdc.nal.usda.gov/food-details/169640/nutrients","ingredient":"はちみつ","edible_grams":40},{"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"fat_g":100,"carbs_g":0,"calories":884,"sodium_mg":2,"protein_g":0,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients","ingredient":"オリーブオイル","edible_grams":30},{"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.1,"calories":149,"sugar_g":1,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients","ingredient":"にんにく","edible_grams":10},{"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38800,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients","ingredient":"細かい塩","edible_grams":4},{"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":64,"calories":251,"protein_g":10.4,"fiber_g":25.3,"sodium_mg":20,"saturated_fat_g":1.39},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients","ingredient":"黒こしょう粉","edible_grams":0.5}]},"image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","gallery":[{"url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","alt":"レモンとはちみつのソースを絡めた鶏むね肉とローストアスパラガス"}],"seo":{"title":"レモンはちみつチキンとアスパラガス | Manual de Cocina","description":"4人分のレモン、はちみつ、にんにくのチキンとローストアスパラガス。先に焼き付け、後からソースを加え、各切れの74°Cを確認。","image_alt":"レモンとはちみつのソースを絡めた鶏むね肉とローストアスパラガス","image_variants":["/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-1x1.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-4x3.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-16x9.webp"],"faq":[{"q":"はちみつを焦がさない方法は？","a":"はちみつなしで鶏肉を焼き付け、火を弱めてからソースを加えます。穏やかに煮て、鶏肉が74°Cに達する前にソースが煮詰まったら短時間ふたをします。濃く暗いソースを目指しません。"},{"q":"生の鶏肉とアスパラガスを一緒に焼けますか？","a":"この配合では別々に調理します。アスパラガスは加熱時間が異なり、先に取り出す場合は生の鶏肉の汁に触れさせません。付け合わせには清潔な天板を使います。"},{"q":"残りの保存と再加熱は？","a":"浅い容器に入れ、2時間以内、32°Cを超える場合は1時間以内に4°C以下で冷蔵します。提案期間は3日以内で、中心74°Cまで1回だけ再加熱します。"}]},"published":false,"editorial_status":"draft","content_html":"<p>鶏むね肉をフライパンで焼き付け、レモン、はちみつ、にんにくのソースで火を通します。グリーンアスパラガスは別にオーブンで焼きます。はちみつは焼き付けた後に弱火で加え、焦げる危険を減らします。このレシピの歴史的な識別情報とURLを保持しています。</p><p>提案量は4人分です。1人分は鶏肉1切れとアスパラガス、ソースそれぞれ全量の4分の1。下準備15分、並行作業を含む加熱25分、休ませる時間5分、合計45分を推定しています。分量、時間、出来上がり量は調理検証前の目安です。各切れの中心が74°Cに達したことを確認してください。色や時間だけで安全な加熱を判断しません。</p>"},{"id":"108de2d0-0504-5da8-8ca1-218801755135","recipe_group_id":"ceed8c90-4245-4396-9095-d1d858d397ac","language":"pt","slug":"frango-com-limao-e-mel-e-aspargos-assados","public_path":"/pt/frango-com-limao-e-mel-e-aspargos-assados","source_url":null,"title":"Frango com limão e mel e aspargos assados","excerpt":"Peitos de frango com molho de limão, mel e alho e aspargos assados separadamente. Proposta para 4, com controle de temperatura a 74°C.","summary":"Os peitos de frango são dourados na frigideira e terminam o cozimento em molho de limão, mel e alho, com aspargos verdes assados separadamente. O mel entra depois de dourar, em fogo baixo, para reduzir o risco de queimar. A identidade e a URL históricas são mantidas.\n\nA proposta rende 4 porções, cada uma com um pedaço de frango e um quarto dos aspargos e do molho. Estimam-se 15 minutos de preparo,25 de cozimento com tarefas em paralelo e 5 de descanso:45 no total. Quantidades, tempos e rendimento aguardam teste de cozinha. Confira 74°C em cada pedaço; cor e tempo não certificam o cozimento.","category":"Pratos principais","category_slug":"platos-principales","difficulty":"Fácil","course":"Prato principal","cuisine":"Cozinha caseira","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":45,"servings":4,"keywords":["frango com limão","frango com mel","aspargos assados","peito de frango ao molho"],"ingredients":[{"name":"peito de frango cru sem pele e sem osso","amount":"800","unit":"g","group":"Frango"},{"name":"aspargos verdes, peso após retirar as bases duras","amount":"600","unit":"g","group":"Acompanhamento"},{"name":"suco de limão espremido na hora","amount":"40","unit":"g","group":"Molho"},{"name":"mel","amount":"40","unit":"g","group":"Molho"},{"name":"azeite de oliva","amount":"30","unit":"g","group":"Cozimento e tempero"},{"name":"alho","amount":"10","unit":"g","group":"Molho"},{"name":"sal fino","amount":"4","unit":"g","group":"Cozimento e tempero"},{"name":"pimenta-do-reino moída","amount":"0.5","unit":"g","group":"Cozimento e tempero"},{"name":"água potável","amount":"60","unit":"ml","group":"Molho"}],"steps":[{"title":"Prepare o frango e os aspargos","content":"Preaqueça o forno a 210°C, com calor em cima e embaixo, sem ventilador. Lave os aspargos, retire as bases duras e pese 600 g já limpos; seque bem. Em outra tábua prepare 4 pedaços de peito que somem 800 g, cerca de 200 g cada, com espessura uniforme de 1,5–2 cm; abra os mais grossos se necessário. Não lave o frango cru. Separe utensílios para alimentos crus e cozidos. Reserve 3 g de sal e 0,25 g de pimenta para o frango, e 1 g de sal e 0,25 g de pimenta para os aspargos.","image_alt":"Aspargos limpos em uma tábua e quatro peitos crus em outra tábua separada","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-01.webp"},{"title":"Misture o molho em um recipiente limpo","content":"Misture 40 g de suco de limão,40 g de mel,10 g de alho picado e 60 ml de água potável. Mexa para dissolver o mel. Mantenha esse molho em recipiente limpo, sem contato com frango cru; não é uma marinada e não se reaproveitam líquidos do prato do frango cru.","image_alt":"Molho de limão, mel e alho sendo misturado em tigela sem contato com frango cru","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-02.webp"},{"title":"Asse os aspargos separadamente","content":"Espalhe os aspargos em uma só camada numa assadeira com 10 g do azeite,1 g de sal e 0,25 g de pimenta. Asse a 210°C por cerca de 12–18 minutos, virando após 8 minutos, até ficarem macios com alguma firmeza e pontas levemente douradas. A espessura altera o tempo. Faça essa tarefa enquanto cozinha o frango; se terminarem antes, mantenha cobertos por pouco tempo enquanto finaliza o molho. Não coloque frango cru nessa assadeira.","image_alt":"Aspargos verdes assados em uma só camada na assadeira, sem frango","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-03.webp"},{"title":"Doure os quatro pedaços de frango","content":"Aqueça os 20 g de azeite restantes em frigideira ampla em fogo médio. Tempere o frango com os 3 g de sal e 0,25 g de pimenta reservados. Coloque os 4 pedaços sem amontoar e doure cerca de 4 minutos de cada lado, aproximadamente 8 minutos no total. Ajuste o fogo para dourar sem queimar. Não adicione mel nem molho nessa fase e não considere o centro já cozido.","image_alt":"Quatro peitos de frango dourando em frigideira ampla, sem molho nem aspargos","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-04.webp"},{"title":"Finalize no molho e confira a temperatura","content":"Abaixe o fogo, junte todo o molho limpo do passo 2 e cozinhe em fervura suave por cerca de 6–8 minutos, virando o frango para envolver. Se engrossar cedo demais, abaixe mais o fogo e tampe brevemente; não deixe o açúcar escurecer ou queimar. Meça cada pedaço com sonda limpa no centro mais grosso, sem tocar a frigideira: deve atingir pelo menos 74°C. Caso contrário, prolongue em fogo baixo e meça novamente. O molho deve ficar fluido e levemente brilhante, não como caramelo grosso.","image_alt":"Peitos cozidos envolvidos em molho leve de limão e mel na frigideira","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-05.webp"},{"title":"Descanse, sirva e conserve com segurança","content":"Passe o frango para uma travessa limpa e descanse 5 minutos. Divida em 4 porções e distribua aspargos e todo o molho com utensílios limpos. Para guardar, coloque as sobras em recipientes rasos e refrigere a 4°C ou menos dentro de 2 horas, ou 1 hora se o ambiente passar de 32°C. Propõe-se consumir em 3 dias e reaquecer cada porção uma única vez até 74°C no centro. Não coloque frango cozido no prato que recebeu o cru.","image_alt":"Um peito com molho de limão e mel ao lado de aspargos assados no prato","image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/paso-06.webp"}],"notes":"Mel não é adequado para menores de 12 meses. Confira alergênicos em produtos embalados e use frango sem salmoura adicionada para se aproximar do cálculo. Não entram mostarda, molho de soja, manteiga, caldo ou acompanhamentos extras. Pode usar aspargos brancos no mesmo peso, ajustando descascamento e cozimento; resultado e nutrientes mudam. Adoçantes não substituem mel de forma equivalente: textura, sabor e redução são diferentes. O suco é a parte comestível contada; não se adicionam rodelas de limão nem ervas ao prato. Pese os aspargos depois de remover as bases duras. A nutrição conta todo o molho e azeite divididos entre 4; se algo ficar na frigideira, a ingestão real pode ser menor. Congelamento e uso de sobras anteriores não foram validados aqui.","nutrition":{"fat_g":13,"calories":372.9,"saturated_fat_g":2.2,"sodium_mg":482,"protein_g":48.5,"sugar_g":11.3,"carbs_g":15.7,"fiber_g":3.3,"estimated":true,"serving_size":"1 das 4 porções propostas","source":"USDA FoodData Central — SR Legacy, abril de 2018","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Oito fichas USDA verificadas por FDC ID no arquivo oficial. Pesos comestíveis crus somados e divididos por 4; conta todo o molho, azeite e tempero. Os 60 ml de água potável não fornecem energia e ficam fora dos oito inputs. Não são calculadas perdas de nutrientes nem divisão exata após cozinhar.","note":"Estimativa, não análise do prato pronto. Salmoura no frango, tipo de mel, perdas e porções reais alteram as cifras; quantidades, tempos e rendimento aguardam teste de cozinha.","inputs":[{"fdc_id":171077,"fdc_description":"Chicken, broiler or fryers, breast, skinless, boneless, meat only, raw","per_100g":{"fat_g":2.62,"calories":120,"saturated_fat_g":0.563,"sodium_mg":45,"protein_g":22.5,"sugar_g":0,"carbs_g":0,"fiber_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171077/nutrients","ingredient":"peito de frango cru sem pele e sem osso","edible_grams":800},{"fdc_id":168389,"fdc_description":"Asparagus, raw","per_100g":{"saturated_fat_g":0.04,"protein_g":2.2,"sugar_g":1.88,"sodium_mg":2,"carbs_g":3.88,"calories":20,"fiber_g":2.1,"fat_g":0.12},"source_url":"https://fdc.nal.usda.gov/food-details/168389/nutrients","ingredient":"aspargos verdes, peso após retirar as bases duras","edible_grams":600},{"fdc_id":167747,"fdc_description":"Lemon juice, raw","per_100g":{"protein_g":0.35,"saturated_fat_g":0.04,"fiber_g":0.3,"sodium_mg":1,"sugar_g":2.52,"fat_g":0.24,"carbs_g":6.9,"calories":22},"source_url":"https://fdc.nal.usda.gov/food-details/167747/nutrients","ingredient":"suco de limão espremido na hora","edible_grams":40},{"fdc_id":169640,"fdc_description":"Honey","per_100g":{"saturated_fat_g":0,"protein_g":0.3,"fiber_g":0.2,"sodium_mg":4,"fat_g":0,"carbs_g":82.4,"calories":304,"sugar_g":82.1},"source_url":"https://fdc.nal.usda.gov/food-details/169640/nutrients","ingredient":"mel","edible_grams":40},{"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"fat_g":100,"carbs_g":0,"calories":884,"sodium_mg":2,"protein_g":0,"saturated_fat_g":13.8,"fiber_g":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients","ingredient":"azeite de oliva","edible_grams":30},{"fdc_id":169230,"fdc_description":"Garlic, raw","per_100g":{"carbs_g":33.1,"calories":149,"sugar_g":1,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17,"protein_g":6.36,"fat_g":0.5},"source_url":"https://fdc.nal.usda.gov/food-details/169230/nutrients","ingredient":"alho","edible_grams":10},{"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"fiber_g":0,"sodium_mg":38800,"saturated_fat_g":0,"protein_g":0,"fat_g":0,"carbs_g":0,"calories":0,"sugar_g":0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients","ingredient":"sal fino","edible_grams":4},{"fdc_id":170931,"fdc_description":"Spices, pepper, black","per_100g":{"fat_g":3.26,"sugar_g":0.64,"carbs_g":64,"calories":251,"protein_g":10.4,"fiber_g":25.3,"sodium_mg":20,"saturated_fat_g":1.39},"source_url":"https://fdc.nal.usda.gov/food-details/170931/nutrients","ingredient":"pimenta-do-reino moída","edible_grams":0.5}]},"image_url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","gallery":[{"url":"/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada.webp","alt":"Peito de frango com molho de limão e mel e aspargos assados"}],"seo":{"title":"Frango com limão, mel e aspargos | Manual de Cocina","description":"Frango com molho de limão, mel e alho para 4 e aspargos assados. Doure primeiro, adicione o molho depois e confira 74°C em cada pedaço.","image_alt":"Peito de frango com molho de limão e mel e aspargos assados","image_variants":["/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-1x1.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-4x3.webp","/recetas/pollo-al-limon-y-miel-con-esparragos-asados/portada-16x9.webp"],"faq":[{"q":"Como evitar que o mel queime?","a":"Doure o frango sem mel e coloque o molho depois de abaixar o fogo. Mantenha fervura suave e tampe brevemente se o molho reduzir antes de o frango alcançar 74°C. Não busque molho escuro e espesso."},{"q":"Posso assar aspargos junto do frango cru?","a":"Esta ficha cozinha separadamente. Os aspargos têm outro tempo e não devem receber líquidos crus de frango se forem retirados antes. Use assadeira limpa para o acompanhamento."},{"q":"Como guardar e reaquecer as sobras?","a":"Refrigere em recipientes rasos dentro de 2 horas, ou 1 hora acima de 32°C, a 4°C ou menos. Consuma nos 3 dias propostos e reaqueça uma vez até 74°C no centro."}]},"published":false,"editorial_status":"draft","content_html":"<p>Os peitos de frango são dourados na frigideira e terminam o cozimento em molho de limão, mel e alho, com aspargos verdes assados separadamente. O mel entra depois de dourar, em fogo baixo, para reduzir o risco de queimar. A identidade e a URL históricas são mantidas.</p><p>A proposta rende 4 porções, cada uma com um pedaço de frango e um quarto dos aspargos e do molho. Estimam-se 15 minutos de preparo,25 de cozimento com tarefas em paralelo e 5 de descanso:45 no total. Quantidades, tempos e rendimento aguardam teste de cozinha. Confira 74°C em cada pedaço; cor e tempo não certificam o cozimento.</p>"}]$pol$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and recipe_group_id = g and language = 'es' and published = false and slug = 'pollo-al-limon-y-miel-con-esparragos-asados' and public_path = '/pollo-al-limon-y-miel-con-esparragos-asados') then
    raise exception 'Estado previo inesperado del grupo pollo-al-limon-y-miel-con-esparragos-asados';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x) or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path en pollo-al-limon-y-miel-con-esparragos-asados';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages en pollo-al-limon-y-miel-con-esparragos-asados';
  end if;
  update public.recipes r set
    title=x.title, excerpt=x.excerpt, summary=x.summary, ingredients=x.ingredients, steps=x.steps,
    category=x.category, prep_time_minutes=x.prep_time_minutes, cook_time_minutes=x.cook_time_minutes,
    total_time_minutes=x.total_time_minutes, servings=x.servings, image_url=x.image_url,
    content_html=coalesce(x.content_html,''), notes=x.notes, difficulty=x.difficulty, course=x.course,
    cuisine=x.cuisine, keywords=x.keywords, nutrition=x.nutrition, gallery=x.gallery, seo=x.seo,
    editorial_status='published', ready_at=ts, published=true
  from jsonb_populate_recordset(null::public.recipes,j) x where r.id=es_id and x.language='es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES de pollo-al-limon-y-miel-con-esparragos-asados afectó % filas', n; end if;
  insert into public.recipes (id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published)
  select x.id,g,x.language,x.slug,x.public_path,null,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,coalesce(x.content_html,''),x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',ts,true
  from jsonb_populate_recordset(null::public.recipes,j) x where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT de traducciones de pollo-al-limon-y-miel-con-esparragos-asados afectó % filas', n; end if;
  if (select count(*) from public.recipes where recipe_group_id=g and published and editorial_status='published' and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo pollo-al-limon-y-miel-con-esparragos-asados no quedó con 7 filas publicadas';
  end if;
  if (select count(distinct language) from public.recipes where recipe_group_id=g) <> 7 then
    raise exception 'El grupo pollo-al-limon-y-miel-con-esparragos-asados no quedó con 7 idiomas únicos';
  end if;
end
$pub$;
